urlset:
{# A local preview without site_url has no canonical URLs to advertise. #}
{% if config.site_url %}
{% for locale, files in i18n_alternates.items() %}
{% for file in files if file.page and file.locale == locale %}

    {{ (config.site_url ~ file.url) | e }}
    {% if file.page.update_date %}{{ file.page.update_date }}{% endif %}
    {% for language, alternate in file.alternates.items() if alternate.locale == language %}

    {% endfor %}

{% endfor %}
{% endfor %}
{% endif %}
